function wrapLines(s,x,y,size){const words=String(s).split(' '),max=Math.floor(900/size),lines=[''];for(const w of words){if((lines.at(-1)+' '+w).trim().length>max&&lines.at(-1))lines.push(w);else lines[lines.length-1]=(lines.at(-1)+' '+w).trim();}return lines.map((v,i)=>`<tspan x="${x}" y="${y+i*(size+4)}">${esc(v)}</tspan>`).join('');}
import{experimentOptions,experimentResult,outputLabel}from './spa1-models.js?v=20261023-physicscomplete01';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const txt=(x,y,s,size=16)=>`<text x="${x}" y="${y}" font-size="${size}" fill="#f7f3eb" text-anchor="middle">${wrapLines(s,x,y,size)}</text>`;const line=(x,y,a,b,c='#b2d3cb',w=2)=>`<path d="M${x} ${y}L${a} ${b}" fill="none" stroke="${c}" stroke-width="${w}"/>`;const arrow=(x,y,a,b,c='#ee947e')=>line(x,y,a,b,c,3)+`<path d="M${a-9*Math.cos(Math.atan2(b-y,a-x)-.5)} ${b-9*Math.sin(Math.atan2(b-y,a-x)-.5)}L${a} ${b}L${a-9*Math.cos(Math.atan2(b-y,a-x)+.5)} ${b-9*Math.sin(Math.atan2(b-y,a-x)+.5)}" fill="none" stroke="${c}" stroke-width="3"/>`;const star=(x,y,r=22)=>`<circle cx="${x}" cy="${y}" r="${r*1.7}" fill="#eec58b" opacity=".08"/><circle cx="${x}" cy="${y}" r="${r}" fill="url(#spa1-sun)"/>`;
export function spaceFigure({kind='system',movie=false,progress=.3,a,b,revealed=false}={}){let k=kind.split('-')[0],o=experimentOptions[k]||experimentOptions.system,A=String(a??o.a[0][0]),B=String(b??o.b[0][0]),p=movie?Math.max(0,Math.min(1,progress)):.3,s='',title='',note='';
if(k==='system'){if(movie){for(let i=0;i<55;i++){let rad=(140-115*p)*(1+(i%3)*.1),ang=i*2.399;s+=`<circle cx="${280+rad*Math.cos(ang)}" cy="${230+rad*.7*Math.sin(ang)}" r="${2+i%3}" fill="${i%2?'#ef947e':'#b4cfce'}" opacity=".65"/>`;}s+=star(280,230,10+25*p)+txt(280,355,p<.5?'Gravity contracts gas and dust':p<.75?'Core temperature and pressure rise':'Fusion begins when conditions permit');title='A nebula contracts into a star';}else{s+=star(170,225,28)+`<ellipse cx="170" cy="225" rx="120" ry="75" fill="none" stroke="#92b7bd"/><circle cx="290" cy="225" r="14" fill="#a6cbc7"/><ellipse cx="290" cy="225" rx="42" ry="28" fill="none" stroke="#92b7bd"/><circle cx="332" cy="225" r="5" fill="#ef947e"/>`+txt(170,310,'Star')+txt(290,340,'Planet')+txt(370,255,'Moon',14)+txt(280,125,'Solar system is a small part of the Milky Way');title='Star, planet and natural satellite';}note='Sizes, separations and times independently enlarged · not a scale model';}
else if(k==='stars'){let path=A==='massive'?['Nebula','Protostar','Main sequence','Red supergiant','Supernova','Neutron star / black hole']:['Nebula','Protostar','Main sequence','Red giant','Shed outer layers','White dwarf'];let active=movie?Math.min(5,Math.floor(p*6)):3;s+=line(90,130,90,365);for(let i=0;i<6;i++){let yy=120+i*49;s+=star(90,yy,i===active?12:6)+txt(310,yy+5,path[i],i===active?18:15);}title=A==='massive'?'High-mass stellar pathway':'Sun-like stellar pathway';note='Stages share display time for clarity, not real stellar duration';}
else if(k==='orbits'){let theta=movie?p*2*Math.PI:A==='top'?-Math.PI/2:0,cx=280,cy=235,r=125,xx=cx+r*Math.cos(theta),yy=cy+r*Math.sin(theta);s+=star(cx,cy,24)+`<circle cx="${cx}" cy="${cy}" r="${r}" fill="none" stroke="#7e9fae" stroke-dasharray="4 5"/><circle cx="${xx}" cy="${yy}" r="12" fill="#a9ceca"/>`+arrow(xx,yy,xx-65*Math.cos(theta),yy-65*Math.sin(theta))+arrow(xx,yy,xx-60*Math.sin(theta),yy+60*Math.cos(theta),'#a9ceca')+txt(280,390,'Coral: inward gravity · pale: tangent velocity',14);title='Gravity turns the velocity direction';note='Circular orbit geometry · period, radius and bodies not calibrated';}
else if(k==='redshift'){let shift=movie?Number(B)*p:Number(B);title='Compare matching spectral lines at longer wavelength';s+=txt(120,115,'Reference',14)+txt(120,180,'Observed',14);for(let i=0;i<4;i++){let xx=200+i*55;s+=line(xx,95,xx,130,'#b9d4ce',4)+line(xx+shift,160,xx+shift,195,'#ef947e',4);}s+=txt(280,225,`${A} nm reference + ${Number(shift.toFixed(1))} nm shift`,14);let scale=1+(movie?p:.4)*.35;for(let i=0;i<5;i++)for(let j=0;j<3;j++){let xx=280+(i-2)*65*scale,yy=325+(j-1)*35*scale;s+=`<circle cx="${xx}" cy="${yy}" r="4" fill="#c0d5d0"/>`;}s+=txt(280,400,'Grid spacing expands; galaxy markers keep their size',13);note='Qualitative analogy · no special centre or calibrated cosmic clock';}
if(a&&b&&revealed)s+=txt(280,460,outputLabel(k,experimentResult(k,A,B).value),14);
return `<svg class="shell-diagram spa1-diagram" viewBox="0 0 560 480" role="img" aria-label="${esc(k+' labelled space model'+(revealed?' with revealed result':''))}"><defs><radialGradient id="spa1-sun" cx="35%" cy="30%"><stop stop-color="#fff1bb"/><stop offset="1" stop-color="#ca865a"/></radialGradient></defs>${txt(280,50,title,15)}${s}${txt(280,430,note,12)}</svg>`;}
